39	const PROCESSING_FEE = 5;
40	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
41	  sword: 100,
42	  amulet: 60,
43	};
44	const FIRST_INSURANCE_RATE = 0.1;
45	
46	const withFirstInsuranceSurcharge = (basePremium: number): number =>
47	  basePremium + basePremium * FIRST_INSURANCE_RATE;
48	
49	const basePremiumOf = (item: Item): number => BASE_PREMIUM_BY_TYPE[item.type];
50	
51	const quotePremium = (items: Item[]): number =>
52	  withFirstInsuranceSurcharge(
53	    items.reduce((sum, item) => sum + basePremiumOf(item), 0),
54	  ) + PROCESSING_FEE;
55	
56	export const runScenario = (scenario: Scenario): ScenarioResult => ({
57	  results: scenario.steps.map((step) => ({
58	    premium: quotePremium("items" in step ? step.items : []),
59	  })),
60	});
